import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-card-1-label';

  const position = config.scenePosition || { x: 0, y: 1, z: 0.06 };
  const rotation = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scale = config.sceneScale || { x: 1, y: 1, z: 1 };

  group.position.set(position.x, position.y, position.z);
  group.rotation.set(rotation.x, rotation.y, rotation.z);
  group.scale.set(scale.x, scale.y, scale.z);

  const colors = {
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    surface: 0x0b0b10
  };

  // Background plane with engineered gradient surface
  const planeWidth = 1.6;
  const planeHeight = 0.4;
  const planeGeo = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const bgMaterial = new THREE.MeshBasicNodeMaterial();

  let map = null;
  const imageUrl = config.assets && config.assets.imageUrl;
  if (imageUrl) {
    map = ctx.textureLoader.load(imageUrl);
    map.wrapS = THREE.ClampToEdgeWrapping;
    map.wrapT = THREE.ClampToEdgeWrapping;
  }

  if (map) {
    const texNode = texture(map, uv());
    const inkColor = vec4(0x16 / 255, 0x16 / 255, 0x1d / 255, 1.0);
    bgMaterial.colorNode = mix(inkColor, texNode, float(0.35));
  } else {
    bgMaterial.colorNode = vec4(0x16 / 255, 0x16 / 255, 0x1d / 255, 1.0);
  }

  const bgMesh = new THREE.Mesh(planeGeo, bgMaterial);
  bgMesh.name = 'hub-collection-card-1-label-bg';
  group.add(bgMesh);

  // Headline text via fontAtlas MSDF
  const textContent = (config.textContent && config.textContent.text) || 'Collection 2';
  const fontSizeEm = 0.34; // headline scale token

  let textMesh = null;
  if (ctx.fontAtlas && typeof ctx.fontAtlas.createText === 'function') {
    textMesh = ctx.fontAtlas.createText({
      text: textContent,
      font: 'Lora',
      weight: 400,
      size: fontSizeEm,
      color: colors.paper,
      align: 'center',
      anchor: 'center'
    });
    if (textMesh) {
      textMesh.position.set(0, 0, 0.001);
      textMesh.name = 'hub-collection-card-1-label-text';
      group.add(textMesh);
    }
  }

  // No cinematic primitives to apply per spec (none listed)

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    planeGeo.dispose();
    bgMaterial.dispose();
    if (map && typeof map.dispose === 'function') {
      map.dispose();
    }
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) {
        if (Array.isArray(textMesh.material)) {
          textMesh.material.forEach(m => m.dispose());
        } else {
          textMesh.material.dispose();
        }
      }
    }
  };

  return group;
}
